#include <thread>
#include <vector>

std::vector<int> squaresInParallel(int count)
{
    std::vector<int> results(static_cast<std::size_t>(count));
    {
        std::vector<std::jthread> threads{};
        for (int i{ 0 }; i < count; ++i)
        {
            threads.emplace_back([&results, i] { results[static_cast<std::size_t>(i)] = i * i; });
        }
    }
    return results;
}

unitTests:
TEST("every slot is filled") { CHECK_EQ(squaresInParallel(6), (std::vector<int>{ 0, 1, 4, 9, 16, 25 })); }
TEST("many threads") { const auto r{ squaresInParallel(64) }; bool ok{ r.size() == 64 }; for (std::size_t i{ 0 }; i < r.size(); ++i) if (r[i] != static_cast<int>(i * i)) ok = false; CHECK(ok); }
TEST("none") { CHECK(squaresInParallel(0).empty()); }

